"""Offline, source-colored comparison of deliberate feature simplifications."""
import argparse
import json
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--absolute', action='store_true')
    args = parser.parse_args()
    out = args.out.resolve()
    report = json.loads((out / 'review.json').read_text())
    for row in report['views']:
        if not (out / row['image']).is_file():
            raise ValueError('missing comparison image')
        if args.absolute:
            row['image'] = str(out / row['image'])
    html = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font:14px var(--font-sans,system-ui);color:var(--foreground,#ddd);line-height:1.5;margin:0}h2{font-size:21px;margin:0 0 6px}p{margin:7px 0 13px}.muted{color:var(--muted-foreground,#999)}.controls{display:flex;gap:10px 16px;flex-wrap:wrap;margin:14px 0}label{display:flex;align-items:center;gap:7px}select,button{font:inherit;background:var(--secondary,#333);color:inherit;border:1px solid var(--border,#666);border-radius:5px;padding:7px;max-width:100%}.numbers{display:flex;gap:24px;flex-wrap:wrap;margin:18px 0}.number b{display:block;font-size:25px}.number span{font-size:12px;color:var(--muted-foreground,#999)}.policy{padding:16px;border-radius:var(--radius,8px);background:var(--secondary,#222);font-size:13px;margin:15px 0}.canvas{padding:16px;background:var(--background,#161616)}.wipe{position:relative;aspect-ratio:1;overflow:hidden}.wipe img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.seam{position:absolute;top:0;bottom:0;width:2px;background:#f1a137}.badge{position:absolute;top:9px;background:#111d;color:white;padding:5px 7px;border-radius:4px;font-size:11px}.badge.left{left:9px}.badge.right{right:9px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair img{width:100%;display:block}.caption{font-size:12px;padding:5px 0}.hidden{display:none}.slider{display:flex;align-items:center;gap:10px;margin:9px 0}.slider input{flex:1;accent-color:#f1a137}.small{font-size:12px}button{cursor:pointer}details{font-size:12px;margin-top:16px}summary{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{padding:6px;border-bottom:1px solid var(--border,#444);text-align:right}td:first-child,th:first-child{text-align:left}.canvas:fullscreen{overflow:auto}.canvas:fullscreen .wipe{aspect-ratio:auto;height:calc(100% - 80px)}@media(max-width:480px){select,button,label{font-size:12px}.controls{gap:8px}.numbers{gap:16px}.number b{font-size:22px}.badge{font-size:9px}}
</style></head><body><h2>Simpler map geometry · feature trials</h2><p class="muted">Compared with the accepted, merged 1 mm model. Actual GLBs and matched views.</p>
<div class="controls"><label>Geometry <select id="role"><option value="collision">Collision as visual</option><option value="visual">Visual</option></select></label><label>Trial <select id="stage"></select></label><label>Subject <select id="group"></select></label><label>View <select id="view"></select></label><label>Layout <select id="layout"><option value="wipe">Wipe</option><option value="pair">Side by side</option></select></label></div>
<div class="numbers"><div class="number"><span>Accepted arena triangles</span><b id="before"></b></div><div class="number"><span>Trial arena triangles</span><b id="after"></b></div><div class="number"><span>Saved triangles</span><b id="saving"></b></div></div><div id="policy" class="policy"></div><p id="subject" class="small"></p>
<div id="canvas" class="canvas"><div id="wipe" class="wipe"><img id="wb" alt="Accepted 1 mm reference"><img id="wa" alt="Simplified candidate"><div id="seam" class="seam"></div><span class="badge left">Accepted 1 mm</span><span class="badge right" id="candidate-label"></span></div><div class="pair hidden" id="pair"><div><img id="pb" alt="Accepted 1 mm reference"><div class="caption">Accepted 1 mm</div></div><div><img id="pa" alt="Simplified candidate"><div class="caption" id="pc"></div></div></div><div id="slider" class="slider"><span class="small">Reference</span><input id="position" type="range" min="0" max="100" value="50" aria-label="Comparison divider"><span class="small">Trial</span></div><button id="enlarge">Enlarge</button></div>
<p class="small muted">1200 × 1200 lossless diagnostic renders with source colors and embedded artwork. Flat, two-sided shading; runtime PBR and moving poses are untested. Collision geometry keeps its existing proxy colors. These trials deliberately change selected features and remain uninstalled. Triangle savings are not measured simulator speedups.</p><details><summary>All trial counts</summary><table><thead><tr><th>Trial</th><th>Visual</th><th>Collision</th></tr></thead><tbody id="totals"></tbody></table></details>
<script>const data=__DATA__,$=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US');const groups={field:'Full arena','tech-core':'Tech Core',rune:'Rune','dart-station':'Dart station',outpost:'Outpost',base:'Base','resource-area':'Resource area','energy-unit':'Energy unit'},views={oblique:'Oblique',reverse:'Reverse',top:'Top',front:'Front',back:'Back',side:'Side',bottom:'Bottom'};for(const [id,options] of [['group',groups],['view',views]])$(id).innerHTML=Object.entries(options).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');$('group').value='tech-core';const levels=new Map(data.levels.map(r=>[r.id,r])),index=new Map(data.views.map(r=>[[r.group,r.view,r.stage].join('|'),r]));if(index.size!==data.levels.length*56)throw Error('Incomplete render matrix');function baseline(){return data.levels.find(r=>r.role===$('role').value&&r.baseline)}function row(stage){const r=index.get([$('group').value,$('view').value,stage].join('|'));if(!r)throw Error('Missing render');return r}function wipe(){const p=$('position').value;$('wa').style.clipPath='inset(0 0 0 '+p+'%)';$('seam').style.left=p+'%'}function update(){const b=baseline(),a=levels.get($('stage').value),br=row(b.id),ar=row(a.id);for(const id of ['wb','pb'])$(id).src=br.image;for(const id of ['wa','pa'])$(id).src=ar.image;$('candidate-label').textContent=a.label;$('pc').textContent=a.label;$('before').textContent=fmt(b.triangles);$('after').textContent=fmt(a.triangles);$('saving').textContent=fmt(b.triangles-a.triangles)+' ('+((1-a.triangles/b.triangles)*100).toFixed(1)+'%)';$('subject').textContent=groups[$('group').value]+': '+fmt(br.triangles)+' → '+fmt(ar.triangles)+' triangles in this selected view subject.';$('policy').textContent=a.note||'Accepted 1 mm reference.';const pair=$('layout').value==='pair';$('wipe').classList.toggle('hidden',pair);$('slider').classList.toggle('hidden',pair);$('pair').classList.toggle('hidden',!pair);wipe()}function role(){const options=data.levels.filter(r=>r.role===$('role').value);$('stage').innerHTML=options.map(r=>'<option value="'+r.id+'">'+r.label+'</option>').join('');$('stage').value=(options.find(r=>r.preferred)||options.filter(r=>!r.baseline).at(-1)||options[0]).id;update()}$('role').onchange=role;for(const id of ['stage','group','view','layout'])$(id).onchange=update;$('position').oninput=wipe;$('enlarge').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('canvas').requestFullscreen().catch(()=>window.open(row($('stage').value).image,'_blank'))};const policies=[...new Set(data.levels.map(r=>r.policy))];$('totals').innerHTML=policies.map(p=>{const v=data.levels.find(r=>r.policy===p&&r.role==='visual'),c=data.levels.find(r=>r.policy===p&&r.role==='collision');return '<tr><td>'+((v||c).policy_label||(v||c).label)+'</td><td>'+(v?fmt(v.triangles):'—')+'</td><td>'+(c?fmt(c.triangles):'—')+'</td></tr>'}).join('');$('wa').onload=()=>console.log('Candidate loaded '+$('wa').naturalWidth+' × '+$('wa').naturalHeight);role();console.log('Validated '+index.size+' subject/view/trial combinations.');</script></body></html>'''.replace('__DATA__', json.dumps(report))
    (out / ('review-inline.html' if args.absolute else 'review.html')).write_text(html)


if __name__ == '__main__':
    main()
